import json
with open("/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0513-6-projects-faith-evidence-ie--claude-sessions-agent-76793097/de5afe88-f903-46ec-8771-03220a2b44ba/tool-results/mcp-agent-ml-research-read_registry-1778794164490.txt") as f:
    data = json.loads(f.read())
result = json.loads(data["result"])
exps = result["data"]["experiments"]
running = {k:v for k,v in exps.items() if v.get("status") == "RUNNING"}
preparing = {k:v for k,v in exps.items() if v.get("status") == "PREPARING"}
done_success = {k:v for k,v in exps.items() if v.get("conclusion") == "success"}
done_negative = {k:v for k,v in exps.items() if v.get("conclusion") == "negative"}

print("=== RUNNING ===")
for k,v in running.items():
    spec = v.get("spec") or {}
    print(f"  {k}: server={spec.get('server','?')}, gpu={spec.get('gpu','?')}, pid={spec.get('pid','?')}")
    print(f"    hypothesis: {v.get('hypothesis','?')[:120]}")

print("\n=== PREPARING ===")
for k,v in preparing.items():
    print(f"  {k}: {v.get('hypothesis','?')[:120]}")

print("\n=== SUCCESS ===")
for k,v in done_success.items():
    m = v.get("metrics") or {}
    print(f"  {k}: {m}")

print("\n=== NEGATIVE ===")
for k,v in done_negative.items():
    m = v.get("metrics") or {}
    print(f"  {k}: {str(m)[:150]}")
